/// Polls `a` then `b` each round, so what `a` queues comes first.
async fn in_order<A: Future, B: Future>(a: A, b: B) -> (A::Output, B::Output) {
    let (mut a, mut b) = (pin!(a), pin!(b));
    let (mut ra, mut rb) = (None, None);
    poll_fn(|cx| {
        if ra.is_none()
            && let Poll::Ready(r) = a.as_mut().poll(cx)
        {
            ra = Some(r);
        }
        if rb.is_none()
            && let Poll::Ready(r) = b.as_mut().poll(cx)
        {
            rb = Some(r);
        }
        match (ra.take(), rb.take()) {
            (Some(x), Some(y)) => Poll::Ready((x, y)),
            (x, y) => {
                (ra, rb) = (x, y);
                Poll::Pending
            }
        }
    })
    .await
}

fn closed(result: Result<(), Error>) -> String {
    let err = result.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Closed, "{err}");
    err.to_string()
}

/// The child exited (or its tree was stopped) while a write waits on a full pipe: every pending and later
/// write settles with `Closed`, and `close` succeeds.
#[test]
fn abandon_settles_pending_writes() {
    let rt = runtime();
    let (stdin, read) = stdin(&rt);
    let (big, more) = (vec![b'x'; 4 * MIB], vec![b'y'; 10]);
    bounded(&rt, async {
        let (r1, r2) = in_order(in_order(stdin.write(&big), stdin.write(&more)), async {
            stdin.abandon();
            stdin.abandon();
        })
        .await
        .0;
        assert!(closed(r1).contains("exited"));
        closed(r2);
        closed(stdin.write(b"z").await);
        stdin.close().await.unwrap();
    });
    drop(read);
}

/// A child that closed its stdin: the write is `Closed` (EPIPE), not a crash, and so is every later one.
#[test]
fn a_closed_pipe_is_closed() {
    let rt = runtime();
    let (stdin, read) = stdin(&rt);
    drop(read);
    bounded(&rt, async {
        assert!(closed(stdin.write(b"x").await).contains("closed its end"));
        closed(stdin.write(b"y").await);
        stdin.close().await.unwrap();
    });
}

/// Dropping stdin closes the child's end once queued writes are done.
#[test]
fn dropping_stdin_closes_the_child_end() {
    let rt = runtime();
    let (stdin, read) = stdin(&rt);
    let got = child_reads(read, Arc::default());
    bounded(&rt, stdin.write(b"last")).unwrap();
    drop(stdin);
    assert_eq!(got.recv_timeout(LIMIT).unwrap(), b"last");
}

pub(super) async fn write(&self, data: &[u8]) -> Result<(), Error> {
    let (reply, done) = oneshot::channel();
    {
        let mut jobs = self.lock();
        if let Some(why) = jobs.shut {
            return Err(Error::stdin_closed(why));
        }
        jobs.queue.push_back(Job::Write(data.to_vec(), reply));
    }
    self.wake.notify_one();
    done.await.unwrap_or_else(|_| Err(Error::stdin_closed(BY_EXIT)))

pub(super) fn abandon(&self) {
    {
        let mut jobs = self.lock();
        jobs.gone = true;
        if let Some(reply) = jobs.current.take() {
            let _ = reply.send(Err(Error::stdin_closed(BY_EXIT)));
        }
        shut(&mut jobs, BY_EXIT);
    }
    self.wake.notify_all();

/// The thread: one job at a time, in order, until stdin is closed, broken or abandoned.
fn run(&self, mut sink: File) {
    loop {
        let (data, close) = {
            let mut jobs = self.lock();
            loop {
                if jobs.gone {
                    return;
                }
                match jobs.queue.pop_front() {
                    Some(Job::Write(data, reply)) => {
                        jobs.current = Some(reply);
                        break (data, None);
                    }
                    Some(Job::Close(reply)) => break (Vec::new(), Some(reply)),
                    None => jobs = self.wake.wait(jobs).unwrap_or_else(PoisonError::into_inner),
                }
            }
        };
        if let Some(reply) = close {
            drop(sink);
            shut(&mut self.lock(), BY_CLOSE);
            let _ = reply.send(Ok(()));
            return;
        }
        let wrote = sink.write_all(&data);
        let mut jobs = self.lock();
        let reply = jobs.current.take();
        let (result, stop) = match wrote {
            Ok(()) => (Ok(()), None),
            Err(e) if e.kind() == ErrorKind::BrokenPipe => (Err(Error::stdin_closed(BY_CHILD)), Some(BY_CHILD)),
            Err(e) => (Err(Error::write_failed(&e)), Some(BY_FAILURE)),
        };
        if let Some(reply) = reply {
            let _ = reply.send(result);
        }
        if let Some(why) = stop {
            shut(&mut jobs, why);
            return;

/// Nothing more is written: queued writes fail with `why`, queued closes succeed. The first reason stays.
fn shut(jobs: &mut Jobs, why: &'static str) {
    let why = *jobs.shut.get_or_insert(why);
    for job in jobs.queue.drain(..) {
        let _ = match job {
            Job::Write(_, reply) => reply.send(Err(Error::stdin_closed(why))),
            Job::Close(reply) => reply.send(Ok(())),
        };
    }
}
